using System;using System.Linq;using System.Reflection;using System.Windows.Forms;using System.Diagnostics;
class AllCgTransitions{static void Wait(int ms){var w=Stopwatch.StartNew();while(w.ElapsedMilliseconds<ms){Application.DoEvents();System.Threading.Thread.Sleep(8);}}[STAThread]static void Main(){var f=BindingFlags.Instance|BindingFlags.NonPublic;using(var g=new Game()){g.Show();var type=typeof(Game);var chapters=(System.Collections.Generic.List<Chapter>)type.GetField("chapters",f).GetValue(g);var save=(Save)type.GetField("save",f).GetValue(g);StoryRoutes.Flag(save,TavernStory.OpeningFlag);StoryRoutes.Flag(save,TavernStory.TransferFlag);StoryRoutes.Flag(save,TavernStory.EntranceFlag);int checkedPages=0;foreach(var c in chapters.Where(c=>TavernStory.Is(c)||WaystationChapterOne.Is(c))){save.sectionAttempts[c.id]=new SectionAttempt{review=true,introShown=true};foreach(int line in TavernStory.Is(c)?new[]{0,12,18}:new[]{0}){type.GetField("current",f).SetValue(g,c);type.GetField("index",f).SetValue(g,line);Action build=()=>type.GetMethod("ShowStory",f).Invoke(g,null);type.GetMethod("TransitionCgPage",f).Invoke(g,new object[]{build});var content=(Panel)type.GetField("content",f).GetValue(g);var overlay=content.Controls.OfType<WhiteSceneReveal>().Single();if(overlay.Bounds!=content.ClientRectangle||overlay.FadeColor!=System.Drawing.Color.Black)throw new Exception("incomplete overlay "+c.id);if((bool)type.GetField("originalPlaying",f).GetValue(g))throw new Exception("audio before reveal");Wait(400);if(!overlay.IsDisposed)throw new Exception("overlay leak");type.GetMethod("StopAudio",f).Invoke(g,null);checkedPages++;}}type.GetMethod("TransitionCgPage",f).Invoke(g,new object[]{(Action)(()=>type.GetMethod("ShowMain",f).Invoke(g,null))});Wait(400);Console.WriteLine("PASS "+checkedPages+" CG dialogue destinations, full-page reveal, delayed voice, and home transition");}}}
